def longest_balanced_subarray(n, arr):
    prefix_sum = 0
    sum_indices = {}
    max_length = -1

    for i, num in enumerate(arr):
        prefix_sum += num

        # If prefix_sum is zero, the subarray from start to current index is balanced
        if prefix_sum == 0:
            max_length = i + 1

        # If the prefix_sum has been seen before, update max_length
        elif prefix_sum in sum_indices:
            prev_index = sum_indices[prefix_sum]
            current_length = i - prev_index
            if current_length > max_length:
                max_length = current_length

        # Store the first occurrence of this prefix_sum
        else:
            sum_indices[prefix_sum] = i

    return max_length if max_length != 0 else -1
```

